  comment CONSTANTS a line 1: F f1 ... fF, the number of facts of pick and then the value of each fact, in order. A line 2: c, the integer of x greater than c. A line 3: c, the integer of x different from c;
  comment P05a. One unknown x. Stage 1: pick(x), a closed world of facts. Stage 2: x greater than c2. Stage 3: x different from c3. pick is given by its facts: when it is posed, each fact, in order, gives x a value, and the values are held all at once, each with a Boolean that says whether it is still a solution. Each comparison is held as posed until x has values, and then tested on each of them. A value that fails a test is dropped, and is not kept;
  integer n, cap, m, i, code, k, j, nf, c2, c3, held, alive;
  Boolean picked, r2, r3;
  integer array xv[1:1000], pk[1:1000];
  Boolean array xa[1:1000];

  procedure test;
  comment every comparison posed so far is tested on every value of x still held, in the order the comparisons were posed. A comparison is held until pick has given x its values;
  if picked then
  begin
    for j := 1 step 1 until nf do
    begin
      if xa[j] then
      begin
        if r2 then begin if ¬(xv[j] > c2) then xa[j] := false end;
        if r3 then begin if ¬(xv[j] ≠ c3) then xa[j] := false end
      end
    end
  end test;

  procedure digits(v);
    value v; integer v;
  comment output adapter: a natural number, its decimal digits with no sign and no spaces, for the name of a case;
  begin
    integer d;
    if v ≥ 10 then digits(v ÷ 10);
    d := v - v ÷ 10 × 10;
    if d = 0 then outstring(1, "0") else if d = 1 then outstring(1, "1") else if d = 2 then outstring(1, "2")
    else if d = 3 then outstring(1, "3") else if d = 4 then outstring(1, "4") else if d = 5 then outstring(1, "5")
    else if d = 6 then outstring(1, "6") else if d = 7 then outstring(1, "7") else if d = 8 then outstring(1, "8")
    else outstring(1, "9")
  end digits;

  procedure relations;
  comment output adapter: the comparisons held, which wait for x to have values;
  begin
    Boolean first;
    first := true;
    if r2 then begin outstring(1, "x gt "); outinteger(1, c2); first := false end;
    if r3 then
