"""Rewrite a report-form ALGOL 60 text into the X1 compiler's representation.
Text only: it executes nothing. Usage: python3 tox1.py IN OUT"""
import re
import sys

UL = "̲"
RESERVED = {"begin", "end", "if", "then", "else", "for", "do", "step", "until", "while",
            "integer", "real", "Boolean", "array", "procedure", "value", "true", "false",
            "label", "own", "switch", "string", "comment", "goto"}

IDIOM_REPORT = "the input and output procedures ininteger, outinteger and outstring as the interpreter gives them (IFIP 1964, systems file)"
IDIOM_X1 = ("the X1 system's input and output procedures read, print, PRINTTEXT and NLCR, as the harness README gives them "
            "(harnesses/algol-60/README.md, 2.1) and its own X1 programs cite them (Kruseman Aretz 2003, chapter 7), and the X1 "
            "compiler's representation, with underlined reserved words and the operator symbols (harness README, 2.1)")


def ul(w):
    w = "boolean" if w == "Boolean" else w
    return "".join(ch + UL for ch in w)


def balanced(s, i):
    """s[i] == '('; return index of the matching ')'."""
    depth = 0
    for j in range(i, len(s)):
        if s[j] == "(":
            depth += 1
        elif s[j] == ")":
            depth -= 1
            if depth == 0:
                return j
    raise ValueError("unbalanced at %d" % i)


def calls(s):
    out = []
    i = 0
    while i < len(s):
        m = re.compile(r"(outstring|outinteger|ininteger)\(").match(s, i)
        if m and (i == 0 or not (s[i - 1].isalnum())):
            j = balanced(s, m.end() - 1)
            args = s[m.end():j]
            name = m.group(1)
            if name == "ininteger":
                a = re.fullmatch(r"0, (.*)", args, re.S)
                out.append("%s := read" % a.group(1))
            elif name == "outinteger":
                a = re.fullmatch(r"1, (.*)", args, re.S)
                out.append("print(%s)" % a.group(1))
            else:
                a = re.fullmatch(r'1, "((?:[^"\\]|\\n)*)"', args, re.S)
                parts = a.group(1).split("\\n")
                stmts = []
                for k, p in enumerate(parts):
                    if k > 0:
                        stmts.append("NLCR")
                    if p:
                        assert "`" not in p and "'" not in p, p
                        stmts.append("PRINTTEXT(`%s')" % p)
                text = "; ".join(stmts)
                if len(stmts) > 1:
                    text = "begin " + text + " end"
                out.append(text)
            i = j + 1
        else:
            out.append(s[i])
            i += 1
    return "".join(out)


def underline(s):
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch == "`":
            j = s.index("'", i)
            out.append(s[i:j + 1])
            i = j + 1
        elif ch.isalpha():
            j = i
            while j < n and s[j].isalnum():
                j += 1
            w = s[i:j]
            if w == "go":
                m = re.compile(r"\s+to\b").match(s, j)
                if m:
                    out.append(ul("goto"))
                    i = m.end()
                    continue
            if w == "comment":
                k = s.index(";", j)
                out.append(ul(w) + s[j:k + 1])
                i = k + 1
                continue
            out.append(ul(w) if w in RESERVED else w)
            i = j
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def convert(src):
    assert src.count(IDIOM_REPORT) == 1
    src = src.replace(IDIOM_REPORT, IDIOM_X1)
    # comments are copied through untouched: split them out first
    pieces = re.split(r"(\bcomment\b[^;]*;)", src)
    pieces = [p if p.startswith("comment") else calls(p) for p in pieces]
    return underline("".join(pieces))


if __name__ == "__main__":
    src = open(sys.argv[1], encoding="utf-8").read()
    open(sys.argv[2], "w", encoding="utf-8").write(convert(src))

